from marshmallow import Schema, fields, ValidationError, EXCLUDE, validates, pre_load


class SignupSchema(Schema):
    class Meta:
        unknown = EXCLUDE

    username = fields.String(required=True)
    email = fields.Email(required=True)
    plan = fields.String(load_default="free")
    age = fields.Integer()

    @validates("username")
    def validate_username(self, value):
        if not value.isalnum():
            raise ValidationError("Username must be alphanumeric.")

    @validates("plan")
    def validate_plan(self, value):
        if value not in {"free", "pro", "team"}:
            raise ValidationError("Plan must be one of 'free', 'pro', or 'team'.")

    @validates("age")
    def validate_age(self, value):
        if not (16 <= value <= 120):
            raise ValidationError("Age must be between 16 and 120 inclusive.")


def validate_signup(data: dict) -> dict:
    """
    Validate sign-up data dict.

    Required fields:
      - username: alphanumeric string
      - email: valid email address

    Optional fields:
      - plan: default "free", must be one of "free", "pro", "team"
      - age: integer, 16 to 120 inclusive

    Unknown keys are dropped.

    Returns cleaned dict with default plan filled in.

    Raises ValueError with .messages attribute (dict[field, list[str]]) on invalid input.
    """
    schema = SignupSchema()
    try:
        return schema.load(data)
    except ValidationError as err:
        exc = ValueError("invalid signup data")
        exc.messages = err.messages
        raise exc
